INSERT INTO tours (id, category, title, location_tags, description, included, excluded, carry, images, status) VALUES ('village-guided-bike-tour', 'Bike Tours', 'Village Guided Bike Tour', ARRAY['Diani','Watamu']::text[], 'Ride through the heart of local village life on this guided bike tour through Diani and Watamu. Your local guide leads the way past homesteads, markets, and everyday coastal life you won''t find in a guidebook.', ARRAY['A local, English-speaking guide','Bike, helmet, and lock','Bottled water']::text[], ARRAY['Personal travel insurance','Tips and gratuities','Hotel pickup outside the core area']::text[], ARRAY['Sunscreen, hat, and sunglasses','Comfortable closed shoes','Camera or phone for photos']::text[], ARRAY['../images/tour-village.svg']::text[], 'Published') ON CONFLICT (id) DO NOTHING;
INSERT INTO tours (id, category, title, location_tags, description, included, excluded, carry, images, status) VALUES ('kaya-kinondo-sacred-forest', 'Bike Tours', 'Kaya Kinondo Sacred Forest', ARRAY['Diani','Tuk Tuk']::text[], 'Ride out to Kaya Kinondo, one of the coast''s sacred Mijikenda forest sites, protected by the local community for generations.', ARRAY['A local guide','Bike, helmet, and lock','Bottled water']::text[], ARRAY['Personal travel insurance','Tips and gratuities']::text[], ARRAY['Sunscreen and a hat','Comfortable closed shoes']::text[], ARRAY['../images/tour-kaya-kinondo.svg']::text[], 'Published') ON CONFLICT (id) DO NOTHING;
INSERT INTO tours (id, category, title, location_tags, description, included, excluded, carry, images, status) VALUES ('giraffe-feeding-adventure', 'Bike Tours', 'Giraffe Feeding Adventure', ARRAY['Diani','Forest Excursions']::text[], 'Cycle to one of the coast''s best-loved wildlife stops for a close encounter with giraffes — hand-feeding included.', ARRAY['A local guide','Bike, helmet, and lock','Bottled water']::text[], ARRAY['Personal travel insurance','Tips and gratuities']::text[], ARRAY['Camera or phone for photos','Comfortable closed shoes']::text[], ARRAY['../images/tour-giraffe.svg']::text[], 'Published') ON CONFLICT (id) DO NOTHING;
INSERT INTO tours (id, category, title, location_tags, description, included, excluded, carry, images, status) VALUES ('elephant-sporting', 'Bike Tours', 'Elephant Sporting', ARRAY['Tuk Tuk','Watamu']::text[], 'Head toward Watamu for a ride centred on spotting elephants in their natural surroundings — a highlight for wildlife lovers.', ARRAY['A local guide','Bike, helmet, and lock (or tuk tuk & driver)','Bottled water']::text[], ARRAY['Personal travel insurance','Tips and gratuities']::text[], ARRAY['Sunscreen and a hat','Camera or phone for photos']::text[], ARRAY['../images/tour-elephant.svg']::text[], 'Published') ON CONFLICT (id) DO NOTHING;
INSERT INTO tours (id, category, title, location_tags, description, included, excluded, carry, images, status) VALUES ('bush-tour', 'Bike Tours', 'Bush Tour', ARRAY['Diani','Kilifi','Tuk Tuk','Watamu']::text[], 'Get off the beaten track on a rugged ride through the coastal bush between Diani, Kilifi, and Watamu.', ARRAY['A local guide','Bike, helmet, and lock','Bottled water']::text[], ARRAY['Personal travel insurance','Tips and gratuities']::text[], ARRAY['Comfortable closed shoes','Cash for personal spending']::text[], ARRAY['../images/tour-bush.svg']::text[], 'Published') ON CONFLICT (id) DO NOTHING;
INSERT INTO tours (id, category, title, location_tags, description, included, excluded, carry, images, status) VALUES ('mangrove-sundowner', 'Marine Excursions', 'Mangrove Tour (Sundowner)', ARRAY['Diani','Kilifi','Watamu']::text[], 'Drift through quiet mangrove channels as the sun sets over the water, one of the coast''s most peaceful ways to end the day.', ARRAY['A local boat guide','Life jacket','Bottled water']::text[], ARRAY['Personal travel insurance','Tips and gratuities']::text[], ARRAY['A light jacket for the evening','Camera or phone for photos']::text[], ARRAY['../images/marine-mangrove.svg']::text[], 'Published') ON CONFLICT (id) DO NOTHING;
INSERT INTO tours (id, category, title, location_tags, description, included, excluded, carry, images, status) VALUES ('full-day-private-dolphin-tour', 'Marine Excursions', 'Full Day Private Dolphin Tour', ARRAY['Diani']::text[], 'Spend a full day out on the water with a private boat, searching the Indian Ocean for dolphins.', ARRAY['A local boat guide','Life jacket','Bottled water']::text[], ARRAY['Personal travel insurance','Tips and gratuities']::text[], ARRAY['Swimwear and a change of clothes','Sunscreen and a hat']::text[], ARRAY['../images/marine-dolphin.svg']::text[], 'Published') ON CONFLICT (id) DO NOTHING;
INSERT INTO tours (id, category, title, location_tags, description, included, excluded, carry, images, status) VALUES ('camel-adventure', 'Marine Excursions', 'Camel Adventure', ARRAY['Diani']::text[], 'Trade two wheels for four legs with a relaxed camel ride along the white sand of Diani beach.', ARRAY['An experienced local handler','Bottled water']::text[], ARRAY['Personal travel insurance','Tips and gratuities']::text[], ARRAY['Sunscreen and a hat','Camera or phone for photos']::text[], ARRAY['../images/marine-camel.svg']::text[], 'Published') ON CONFLICT (id) DO NOTHING;
INSERT INTO tours (id, category, title, location_tags, description, included, excluded, carry, images, status) VALUES ('beach-tour', 'Marine Excursions', 'Beach Tour', ARRAY['Diani']::text[], 'A guided walk or ride along Diani''s beachfront, taking in the coastline at an easy pace.', ARRAY['A local guide','Bottled water']::text[], ARRAY['Personal travel insurance','Tips and gratuities']::text[], ARRAY['Sunscreen and a hat','Comfortable footwear']::text[], ARRAY['../images/marine-beach.svg']::text[], 'Published') ON CONFLICT (id) DO NOTHING;
INSERT INTO tours (id, category, title, location_tags, description, included, excluded, carry, images, status) VALUES ('snake-show-and-school', 'Forest Excursions', 'Snake Show And School', ARRAY['Diani','Watamu']::text[], 'An educational, family-friendly stop to see the coast''s native snake species up close in a safe, controlled setting.', ARRAY['A local guide','Entry to the site','Bottled water']::text[], ARRAY['Personal travel insurance','Tips and gratuities']::text[], ARRAY['Comfortable closed shoes','Camera or phone for photos']::text[], ARRAY['../images/forest-snake-show.svg']::text[], 'Published') ON CONFLICT (id) DO NOTHING;
INSERT INTO tours (id, category, title, location_tags, description, included, excluded, carry, images, status) VALUES ('ruins-of-mnarani', 'Forest Excursions', 'Ruins of Mnarani', ARRAY['Kilifi']::text[], 'Explore the historic Mnarani ruins overlooking Kilifi Creek, remnants of a Swahili settlement steeped in coastal history.', ARRAY['A local guide','Entry to the site','Bottled water']::text[], ARRAY['Personal travel insurance','Tips and gratuities']::text[], ARRAY['Insect repellent','Sunscreen and a hat']::text[], ARRAY['../images/forest-mnarani-ruins.svg']::text[], 'Published') ON CONFLICT (id) DO NOTHING;
INSERT INTO tours (id, category, title, location_tags, description, included, excluded, carry, images, status) VALUES ('monkey-trails-and-conservation-centre', 'Forest Excursions', 'Monkey Trails And Conservation Centre', ARRAY['Diani']::text[], 'Wander forest trails home to local monkey populations, with a conservation-focused guide sharing insight into the ecosystem.', ARRAY['A local guide','Entry to the site','Bottled water']::text[], ARRAY['Personal travel insurance','Tips and gratuities']::text[], ARRAY['Insect repellent','Comfortable closed shoes']::text[], ARRAY['../images/forest-monkey-trails.svg']::text[], 'Published') ON CONFLICT (id) DO NOTHING;
INSERT INTO tours (id, category, title, location_tags, description, included, excluded, carry, images, status) VALUES ('gede-ruins-tour', 'Forest Excursions', 'Gede Ruins Tour', ARRAY['Watamu']::text[], 'Discover the ancient Swahili ruins of Gede, hidden within the forest near Watamu and among the coast''s best-preserved historic sites.', ARRAY['A local guide','Entry to the site','Bottled water']::text[], ARRAY['Personal travel insurance','Tips and gratuities']::text[], ARRAY['Insect repellent','Comfortable closed shoes']::text[], ARRAY['../images/forest-gede-ruins.svg']::text[], 'Published') ON CONFLICT (id) DO NOTHING;
