INSERT INTO faqs (id, page, question, answer) VALUES ('36876350-d8b6-4f30-5a26-8e591ec4b791', 'about', 'What types of bikes do you offer for rent?', 'We offer a variety of bikes for rent to suit every rider''s needs and preferences. Our selection includes classic bicycles for leisurely rides, mountain bikes for off-road adventures, and electric bikes for effortless exploration.') ON CONFLICT (id) DO NOTHING;
INSERT INTO faqs (id, page, question, answer) VALUES ('34229832-b246-64f1-ee48-1355be31377d', 'about', 'Do you provide guided tours for bike excursions?', 'Absolutely! Our bike excursions are led by experienced local guides who will accompany you on your adventure, sharing insights into the area''s history, culture, and natural beauty.') ON CONFLICT (id) DO NOTHING;
INSERT INTO faqs (id, page, question, answer) VALUES ('fbe1b3cf-8cda-f0c0-a7f4-70fb4e06c245', 'about', 'Are helmets provided with bike rentals?', 'Yes, safety is our top priority. We provide helmets with every bike rental to ensure that our riders can explore Diani with peace of mind.') ON CONFLICT (id) DO NOTHING;
INSERT INTO faqs (id, page, question, answer) VALUES ('004ea661-7a95-ce94-f7ba-bc3c5495f151', 'about', 'Can I customize a day trip to suit my interests?', 'Of course! We understand that every traveler is unique, which is why we offer customizable day trips tailored to your preferences. Whether you''re interested in biking, cultural experiences, or outdoor adventures, we''ll work with you to create the perfect itinerary for an unforgettable day in Diani.') ON CONFLICT (id) DO NOTHING;
INSERT INTO faqs (id, page, question, answer) VALUES ('f85e9bc5-889c-aa90-9749-f6312918050a', 'rentals', 'What types of bikes can I rent?', 'We offer Electric, Mountain, Manual, and Kids bikes, so there''s an option whether you want an effortless ride, a rugged off-road trail, a relaxed cruise, or a safe first ride for younger riders.') ON CONFLICT (id) DO NOTHING;
INSERT INTO faqs (id, page, question, answer) VALUES ('42422b8a-ac94-4a53-af06-5bc00d677f10', 'rentals', 'What''s included with every rental?', 'Every rental comes with a helmet and a bike lock, and you can add an optional front basket at no extra request — handy for beach bags or shopping trips.') ON CONFLICT (id) DO NOTHING;
INSERT INTO faqs (id, page, question, answer) VALUES ('0a8a969c-78cf-2b6c-8da9-350c1576ad88', 'rentals', 'Do you offer half-day and full-day rates?', 'Yes — every bike type is available on a half-day or full-day rate. See the pricing above for the current rates per bike.') ON CONFLICT (id) DO NOTHING;
INSERT INTO faqs (id, page, question, answer) VALUES ('1b0665d8-48a7-8a41-49d9-711e8a4fb73e', 'rentals', 'Can I rent a bike without booking a guided tour?', 'Absolutely — self-guided rentals are available if you''d rather explore at your own pace. If you''d prefer a local guide, take a look at our Bike Tours.') ON CONFLICT (id) DO NOTHING;
INSERT INTO faqs (id, page, question, answer) VALUES ('a42beecd-42d8-0591-cb3a-5d537087db80', 'rentals', 'Are helmets provided for kids too?', 'Yes, safety is our top priority for every rider — including kids. Every Kids Bike rental comes with a properly fitted helmet.') ON CONFLICT (id) DO NOTHING;
